prompt.output_format:
Return ONLY valid JSON.

Do not return Markdown.

Do not return explanations outside JSON.

Do not use code fences.

Use exactly this structure:

{
  "photo_quality": {
    "value": "good | fair | poor",
    "reason": "short reason"
  },

  "site_type": {
    "value": "existing_road | kaccha_track | open_land | unclear",
    "confidence": "low | medium | high"
  },

  "recommended_mode": {
    "value": "repair | new_construction | unclear",
    "confidence": "low | medium | high",
    "reason": "short reason based only on visible evidence"
  },

  "new_road_notes": {
    "terrain": "flat | sloping | uneven | not_visible",
    "drainage_concerns": "short observation",
    "obstacles": [
      "trees",
      "poles",
      "structures",
      "water_body"
    ],
    "cc_vs_bt_factors": "neutral factors only"
  },

  "road_type": {
    "value": "earthen | moorum_or_gravel | WBM | bituminous_BT | concrete_CC | paver_block | unclear",
    "confidence": "low | medium | high"
  },

  "surface_condition": "one or two short factual sentences",

  "defects": [
    {
      "type": "defect type",
      "severity": "minor | moderate | severe",
      "confidence": "low | medium | high",
      "note": "short factual observation"
    }
  ],

  "suggested_works": [
    {
      "work": "short work name",
      "reason": "why the work may be relevant",
      "suggested_chapters": [
        "chapter name"
      ],
      "search_keywords": [
        "keyword 1",
        "keyword 2",
        "keyword 3"
      ],
      "confidence": "low | medium | high"
    }
  ],

  "suggested_parameters": [
    {
      "name": "parameter that engineer/user must provide",
      "why_needed": "short reason"
    }
  ],

  "limitations": "short description of what cannot be determined from the photograph"

}
